using FluxoOS.Domain;
using Xunit;
namespace FluxoOS.UnitTests;

public class WorkflowTests {
    private static ServiceOrder Open()=>new(){TechnicianId="tech-1",CreatedAt=DateTimeOffset.UtcNow.AddDays(-1),DueAt=DateTimeOffset.UtcNow.AddDays(2)};
    private static ServiceOrder Quoted(){var o=Open();o.Transition(OrderStatus.Diagnosing,"",null,"Técnico",false);o.Diagnose("Falha no SSD confirmada.","Técnico");o.ReviseQuote([new(){Description="SSD",Quantity=2,UnitPrice=120.35m}],DateTimeOffset.UtcNow.AddDays(7),DateTimeOffset.UtcNow,"Técnico");return o;}
    private static ServiceOrder Approved(){var o=Quoted();o.SubmitQuote("Técnico");o.DecideQuote(true,"Telefone","Cliente confirmou o orçamento.",DateTimeOffset.UtcNow,"Admin");return o;}

    [Fact] public void Full_repair_records_every_step_and_receiver(){var o=Approved();o.Transition(OrderStatus.Repairing,"",null,"Técnico",false);o.Transition(OrderStatus.Ready,"SSD instalado e testes concluídos.",null,"Técnico",false);o.Transition(OrderStatus.Delivered,"Conferido.","Ana", "Admin",true);Assert.Equal(OrderStatus.Delivered,o.Status);Assert.Equal("Ana",o.Receiver);Assert.Equal(8,o.Events.Count);Assert.All(o.Events,e=>Assert.False(string.IsNullOrWhiteSpace(e.Actor)));}
    [Fact] public void Diagnosis_requires_assigned_technician(){var o=Open();o.TechnicianId=null;Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Diagnosing,"",null,"Admin",true));Assert.Equal(OrderStatus.Received,o.Status);}
    [Fact] public void Repair_without_approval_is_rejected(){var o=Quoted();Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Repairing,"",null,"Técnico",false));Assert.Equal(OrderStatus.Diagnosing,o.Status);}
    [Fact] public void Revision_preserves_approved_snapshot_and_requires_new_approval(){var o=Approved();var previous=o.CurrentQuote!;o.ReviseQuote([new(){Description="Novo componente",Quantity=1,UnitPrice=400}],DateTimeOffset.UtcNow.AddDays(7),DateTimeOffset.UtcNow,"Técnico");Assert.Equal(QuoteStatus.Superseded,previous.Status);Assert.Equal(240.70m,previous.Total);Assert.Equal(2,o.CurrentQuote!.Revision);Assert.Equal(400,o.CurrentQuote.Total);Assert.Equal(OrderStatus.Diagnosing,o.Status);Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Repairing,"",null,"Técnico",false));}
    [Fact] public void Repairing_order_cannot_rewrite_quote(){var o=Approved();o.Transition(OrderStatus.Repairing,"",null,"Técnico",false);Assert.Throws<RuleException>(()=>o.ReviseQuote([new(){Description="Troca",Quantity=1,UnitPrice=200}],DateTimeOffset.UtcNow.AddDays(1),DateTimeOffset.UtcNow,"Técnico"));Assert.Single(o.Quotes);}
    [Fact] public void Expired_quote_cannot_be_approved(){var o=Quoted();o.SubmitQuote("Técnico");o.CurrentQuote!.ValidUntil=DateTimeOffset.UtcNow.AddMinutes(-1);Assert.Throws<RuleException>(()=>o.DecideQuote(true,"Telefone","Sim",DateTimeOffset.UtcNow,"Admin"));Assert.Equal(OrderStatus.AwaitingApproval,o.Status);}
    [Fact] public void Declined_quote_can_be_returned_without_claiming_repair(){var o=Quoted();o.SubmitQuote("Técnico");o.DecideQuote(false,"Presencial","Cliente preferiu não reparar.",DateTimeOffset.UtcNow,"Admin");o.Transition(OrderStatus.Delivered,"Devolvido sem reparo.","Cliente", "Admin",true);Assert.Empty(o.WorkPerformed);Assert.Equal(QuoteStatus.Declined,o.CurrentQuote!.Status);Assert.Equal(OrderStatus.Delivered,o.Status);}
    [Fact] public void Revision_requires_diagnosis(){var o=Open();o.Status=OrderStatus.Diagnosing;Assert.Throws<RuleException>(()=>o.ReviseQuote([new(){Description="Peça",Quantity=1,UnitPrice=10}],DateTimeOffset.UtcNow.AddDays(1),DateTimeOffset.UtcNow,"Técnico"));}
    [Fact] public void Completion_requires_description_of_work(){var o=Approved();o.Transition(OrderStatus.Repairing,"",null,"Técnico",false);Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Ready," ",null,"Técnico",false));}
    [Fact] public void Delivery_requires_receiver_and_administrator(){var o=Approved();o.Status=OrderStatus.Ready;Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Delivered,"","Ana","Técnico",false));Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Delivered,"","", "Admin",true));}
    [Theory][InlineData(false,"Cliente cancelou")][InlineData(true,"")]
    public void Cancellation_requires_admin_and_reason(bool admin,string reason){var o=Open();Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Cancelled,reason,null,"Usuário",admin));}
    [Theory][InlineData(OrderStatus.Delivered)][InlineData(OrderStatus.Cancelled)]
    public void Closed_order_preserves_history_but_accepts_correction_note(OrderStatus status){var o=Open();o.Status=status;Assert.Throws<RuleException>(()=>o.Assign("tech-2","Admin"));Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Diagnosing,"",null,"Admin",true));o.AddNote("Correção de identificação registrada sem reabrir.","Admin");Assert.Single(o.Events);Assert.Equal(status,o.Status);}
    [Theory][InlineData(0,10)][InlineData(-1,10)][InlineData(1001,10)][InlineData(1,-1)][InlineData(1,100001)][InlineData(1,1.234)]
    public void Invalid_item_cannot_enter_quote(int quantity,decimal price){var o=Quoted();Assert.Throws<RuleException>(()=>o.ReviseQuote([new(){Description="Item",Quantity=quantity,UnitPrice=price}],DateTimeOffset.UtcNow.AddDays(1),DateTimeOffset.UtcNow,"Técnico"));Assert.Single(o.Quotes);}
    [Fact] public void Monetary_sum_is_decimal_and_exact(){var o=Quoted();o.ReviseQuote([new(){Description="Serviço",Quantity=3,UnitPrice=0.10m},new(){Description="Peça",Quantity=1,UnitPrice=0.20m}],DateTimeOffset.UtcNow.AddDays(1),DateTimeOffset.UtcNow,"Técnico");Assert.Equal(0.50m,o.CurrentQuote!.Total);}
    [Fact] public void Repeated_decision_does_not_duplicate_events(){var o=Approved();var count=o.Events.Count;Assert.Throws<RuleException>(()=>o.DecideQuote(true,"Telefone","Repetição",DateTimeOffset.UtcNow,"Admin"));Assert.Equal(count,o.Events.Count);}
    [Fact] public void Repeated_delivery_is_rejected(){var o=Approved();o.Status=OrderStatus.Ready;o.Transition(OrderStatus.Delivered,"","Ana","Admin",true);Assert.Throws<RuleException>(()=>o.Transition(OrderStatus.Delivered,"","Ana","Admin",true));Assert.Single(o.Events,e=>e.Detail.Contains("Ready → Delivered"));}
    [Fact] public void Decision_cannot_be_future_or_before_intake(){var o=Quoted();o.SubmitQuote("Técnico");Assert.Throws<RuleException>(()=>o.DecideQuote(true,"Telefone","Sim",DateTimeOffset.UtcNow.AddDays(1),"Admin"));Assert.Throws<RuleException>(()=>o.DecideQuote(true,"Telefone","Sim",o.CreatedAt.AddSeconds(-1),"Admin"));}
    [Fact] public void Version_changes_with_each_recorded_operation(){var o=Open();var before=o.Version;o.AddNote("Equipamento conferido.","Admin");Assert.NotEqual(before,o.Version);Assert.Single(o.Events);}
    public static IEnumerable<object[]> InvalidTransitions(){foreach(var from in Enum.GetValues<OrderStatus>())foreach(var to in Enum.GetValues<OrderStatus>()){if(to==OrderStatus.Cancelled||from is OrderStatus.Cancelled or OrderStatus.Delivered)continue;if((from,to) is (OrderStatus.Received,OrderStatus.Diagnosing) or (OrderStatus.Approved,OrderStatus.Repairing) or (OrderStatus.Repairing,OrderStatus.Ready) or (OrderStatus.Ready,OrderStatus.Delivered) or (OrderStatus.Declined,OrderStatus.Delivered))continue;yield return [from,to];}}
    [Theory][MemberData(nameof(InvalidTransitions))]
    public void Arbitrary_transition_cannot_skip_workflow(OrderStatus from,OrderStatus to){var o=Open();o.Status=from;Assert.Throws<RuleException>(()=>o.Transition(to,"Texto", "Ana","Admin",true));Assert.Equal(from,o.Status);}
}
